{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Meperidine absolute oral bioavailability was 0.48 in healthy volunteers, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Tolfenamic acid absolute oral bioavailability averaged 60% in healthy volunteers after oral capsules, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Isradipine median absolute oral bioavailability was 16% in healthy subjects, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Most high-assay-transfer evidence molecules show absolute oral bioavailability values well above 20%, including 48%, 60%, and 68%; only isradipine falls below 20% in healthy subjects. High bioavailability is therefore better supported.",
  "evidence_gaps": [
    "One high-transfer molecule (isradipine) has healthy-subject values below 20%, and medifoxamine is borderline at 21%.",
    "Some records come from altered conditions such as cirrhosis or are qualitative, but numeric healthy-subject data dominate the decision."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

